import type { GenRoute } from "../lib/router/tree";
import { routes as mount_admin } from "./routes.admin.gen";
import { RequireAuth as m2 } from "./require-auth";
import { RootLayout as m3 } from "./root-layout";

/** The ops app's routes. */
export const routes: GenRoute[] = [
  { layout: m3, children: [
    { path: "/login", page: () => import("../features/auth/ui/sign-in-page").then((m) => ({ default: m.SignInPage })) },
    { layout: m2, children: [
      { path: "/", page: () => import("../routes/ops/(signed-in)/page") },
      ...mount_admin,
      { path: "/*", page: () => import("../routes/ops/(signed-in)/[...rest]/page") },
    ] },
  ] },
];

/** The path pattern of every page of the ops app. */
export type RoutePath =
  | "/"
  | "/*"
  | "/login";
